"""Offline Batch6 gallery, reusing established Chapter2 review styles/controls."""
from pathlib import Path
from html import escape
import json
ROOT=Path(__file__).resolve().parent
assets=json.loads((ROOT/'manifest.json').read_text())['assets']
records=json.loads((ROOT/'generation-records.json').read_text())['assets']
descriptions={
'A':'Pale-green emergency credential: attached silver clip, three-leaf emblem, shortened ACTING DIRECTOR title and unlettered authorization stamp. Real binary alpha on96×96.',
'B':'The independently authored565×451 inspector shows the complete ACTING DIRECTOR OF VEGETATION title. A targeted source-color cleanup reduces paper grain; the original remains preserved.',
'C':'The sealed rounded-rectangular cargo case at inventory size: two secured front catches, bevelled lid, teal band and leaf label. Real binary alpha; no escaped contents.',
'D':'A detailed independent view of the same closed silver/teal case established by the approved Customs scene. KEEP SEALED is readable; no rupture, germination or later outcome.'}
comparisons=[('director-slot-inspector','Acting Director: independent slot and inspector variants'),('cargo-slot-inspector','Certified cargo: independent slot and inspector variants'),('credential-inspector-continuity','Approved Examiner credential → new Acting Director credential'),('cargo-scene-continuity','Approved Agricultural Customs container → new slot → new inspector'),('slot-presentation-continuity','Approved slot presentation beside the new item icons'),('credential-color-cleanup','Preserved first native inspector → targeted source-color cleanup')]
def fig(stem,title,cls=''):
 return f'<figure class="{cls}"><div class="scroll"><img class="pixel scaled" data-stem="{stem}" src="previews/{stem}-native.png" alt="{escape(title)}"></div><figcaption>{escape(title)}</figcaption></figure>'
cards=[]
for a in assets:
 k=a['id'];stem=Path(a['candidatePath']).stem;title={'A':'Acting Director — inventory','B':'Acting Director — inspector','C':'Certified seed case — inventory','D':'Certified seed case — inspector'}[k];w,h=a['dimensions'];alpha=' alpha' if a['mode']=='RGBA' else ''
 image=f'<figure><div class="scroll{alpha}"><img class="pixel scaled" data-stem="{stem}" src="previews/{stem}-native.png" alt="{escape(title)}"></div></figure>'
 extra='<a href="prompts/B-v01.txt">Initial prompt</a>' if k=='B' else ''
 cards.append(f'<article class="asset" id="asset-{k}" data-width="{w}" data-height="{h}"><header><div class="eyebrow">{k} / {a["mode"]} {w}×{h} / generated, unselected</div><h3>{title}</h3><div class="id"><code>{a["registryKey"]}</code></div><p>{descriptions[k]}</p></header>'+image+f'<div class="asset-links"><a href="{a["candidatePath"]}">Native candidate PNG</a><a href="previews/{stem}-4x.png">Exact4× preview</a><a href="{a["source"]}">Original detailed source</a><a href="{records[k]["prompt"]}">Exact prompt</a>{extra}</div></article>')
docs=[('README.md','Batch6 handoff','Files, source pins and reproducible item processing'),('BATCH5_APPROVAL.md','Batch5 final approval','Five selected source hashes; all96 public images verified'),('CANDIDATE_HASHES.md','Four paths and hashes','Exact registry mappings and SHA-256 values'),('ARTWORK_CONTINUITY_REVIEW.md','Visual findings','Item-pair consistency, inspector cleanup and native limits'),('STORY_CONTINUITY.md','Canonical context','Credentials, sealed cargo and explicit owner shape direction'),('VISUAL_DIRECTION.md','Visual direction','Approved credential and Customs reference identities'),('qa.json','Pixel, palette and alpha QA','Dimensions, margins, opacity, colors and exact4×'),('manifest.json','Candidate manifest','Source hashes, transforms and generated statuses'),('generation-records.json','Generation provenance','Four independent originals, targeted cleanup and exact prompts'),('SOURCE_SHA256SUMS.txt','Original source hashes','Renders, prompts, approved references and canon snapshots'),('REMAINING_QUEUE.md','Remaining14 records','Batch7 treatment/Focus and Batch8 death illustrations'),('build_review.py','Reproducible processing','Alpha threshold, native fit, palette and preview verification'),('STORYBOARD_SYNC.md','Publication receipt','Generated statuses, canonical QA and Pages verification')]
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Biology Park · Batch6 · Review</title><link rel="stylesheet" href="gallery.css"></head><body><header><div class="eyebrow">The Acceptable Error / Chapter2 / Batch6 / November17,2026</div><h1>Credentials<br><span style="color:#b9c9b1">and courier cargo.</span></h1><p><span class="status">Four generated candidates · Art Director review pending</span></p><p class="muted">Batch5 is finally owner-approved and registered. All96 selected public-art hashes have been verified. These four new item candidates remain generated and unselected; all earlier approved pixels are unchanged.</p><nav aria-label="Review sections"><a href="#items">Four candidates</a><a href="#pairs">Pairs and approved references</a><a href="#alpha">Transparency checks</a><a href="#evidence">QA and sources</a></nav></header><div class="toolbar"><div class="toolbar-inner"><div class="button-group" role="group" aria-label="Preview scale"><span class="group-label">View</span><button type="button" data-scale="1" aria-pressed="true">Native pixels</button><button type="button" data-scale="4" aria-pressed="false">Exact4×</button></div><div class="button-group" role="group" aria-label="Inventory transparency backdrop"><span class="group-label">Icon backdrop</span><button type="button" data-backdrop="checker" aria-pressed="true">Checker</button><button type="button" data-backdrop="dark" aria-pressed="false">Dark</button><button type="button" data-backdrop="light" aria-pressed="false">Light</button></div><span class="muted" style="font-size:12px">Integer nearest-neighbor PNGs · full-size images scroll</span></div></div><main><section id="items"><div class="eyebrow">A–D / genuine item artwork</div><h2>Four independent item candidates</h2><p class="note">Slots are transparent RGBA96×96; inspectors are opaque RGB565×451. Exact4× review enlargements are384×384 and2260×1804. Inspector views are separate generations, not enlarged inventory icons. Detailed originals and exact prompts are preserved.</p>'''
html+=''.join(cards)
html+='</section><section id="pairs"><div class="eyebrow">Same object / two presentations</div><h2>Pairs and approved artwork</h2><p>The pale-green card belongs to the approved credential family. The sealed cargo case follows the approved rounded-rectangular Customs container. The owner’s explicit shape direction takes precedence over older cylinder wording in the item prose, which remains unchanged.</p>'
html+=''.join(fig(s,t,'comparison') for s,t in comparisons)
html+='</section><section id="alpha"><div class="eyebrow">True transparency / native margins</div><h2>Inspect the inventory masks</h2><p>The two slot sources have genuine transparency. The established processing samples their alpha with NEAREST, thresholds at128, crops transparent padding and fits the intact object within88×88 on a96×96 canvas. Final alpha is strictly0/255; hidden RGB is zero.</p>'
for k,title in [('A','Acting Director credential'),('C','Certified seed case')]:html+=fig(k+'-alpha-inspection',title+' on checker, dark and light')+fig(k+'-alpha-mask',title+' native binary alpha: white = object')
html+='</section><section id="evidence"><div class="eyebrow">Evidence / provenance / handoff</div><h2>Technical and visual review</h2><figure><div class="scroll"><img class="pixel" src="previews/palette.png" alt="Exact existing industrial64-color palette"></div><figcaption>Existing palette, no dithering. Small icon detail and inspector surface modeling remain visual-review questions; technical checks do not establish approval.</figcaption></figure><div class="docs">'
html+=''.join(f'<a class="doc" href="{p}"><strong>{title}</strong><span>{detail}</span></a>' for p,title,detail in docs)
html+='''</div><details><summary>Preserved inspector and processing history</summary><p>The first badge inspector’s source texture became conspicuous after native palette mapping. A targeted built-in source-color edit simplifies the paper/background treatment while preserving identity and title. Both raw generations, exact prompts and first native exports remain preserved.</p><p><a href="generation-source/B-acting-director-badge-inspect-v01.png">First raw source</a> · <a href="generation-source/B-acting-director-badge-inspect-v02.png">Current raw source</a> · <a href="processing-history/normalization-v01/manifest.json">First normalized exports</a> · <a href="processing-history/radius12-trial/manifest.json">Preserved color-consolidation trial, not used</a></p></details><p>Native slot and inspector PNGs are the future integration handoff. No production paths or gameplay integration are assigned. Focus dimensions and death-screen specifications remain unchanged; Batch7 has not started.</p></section></main><footer>Four generated item candidates · no self-approval or gameplay integration · approved Chapter2 art and story source preserved.</footer><script>'use strict';function setScale(scale){document.querySelectorAll('[data-scale]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.scale)===scale)));document.querySelectorAll('.scaled').forEach(img=>{img.removeAttribute('width');img.removeAttribute('height');img.src='previews/'+img.dataset.stem+(scale===4?'-4x.png':'-native.png');});}document.querySelectorAll('[data-scale]').forEach(b=>b.addEventListener('click',()=>setScale(Number(b.dataset.scale))));document.querySelectorAll('[data-backdrop]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.alpha').forEach(x=>{x.classList.remove('dark','light');if(b.dataset.backdrop!=='checker')x.classList.add(b.dataset.backdrop);});document.querySelectorAll('[data-backdrop]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));}));</script></body></html>'''
(ROOT/'index.html').write_text(html)
print('Offline item gallery built:four cards,six comparisons,alpha backdrops,native/exact4x.')
